/* ---- reference scalar inference (any ISA), for correctness checks ---- */
static void hc_reference_logits(const float *raw_in, float *logits) {
    float a[64], b[64];
    for (int k = 0; k < 15; k++)
        a[k] = (raw_in[k] - HC_FEATURE_MEAN[k]) / HC_FEATURE_STD[k];
    float *ib = a, *ob = b;
    const float *const WREF[] = {HC_W0_REF, HC_W1_REF, HC_W2_REF};
    const float *const BREF[] = {HC_B0, HC_B1, HC_B2};
    for (int L = 0; L < 3; L++) {
        int si = HC_LAYER_SIZES[L], so = HC_LAYER_SIZES[L + 1], last = (L == 2);
        for (int j = 0; j < so; j++) {
            float acc = BREF[L][j];
            for (int k = 0; k < si; k++) acc += WREF[L][k * so + j] * ib[k];
            ob[j] = last ? acc : (acc > 0.0f ? acc : 0.0f);
        }
        float *t = ib; ib = ob; ob = t;
    }
    for (int i = 0; i < 3; i++) logits[i] = ib[i];
}
static int hc_reference_predict(const float *raw_in) {
    float lg[3]; hc_reference_logits(raw_in, lg);
    int best = 0; for (int i = 1; i < 3; i++) if (lg[i] > lg[best]) best = i;
    return best;
}

